def translate(text, language="en"):
    if language == "it":
        return ITALIAN.get(text, text)
    return text


def number(value, decimals=0, language="en"):
    result = f"{value:,.{decimals}f}"
    if language == "it":
        return result.replace(",", " ").replace(".", ",")
    return result.replace(",", " ")
